<?php $titulo='Simulador de política'; $modulo='agenda'; ?>
<div class="mb-3"><h4 class="mb-1">Simular decisão de acesso</h4><p class="text-muted mb-0">Avalia grupo, horário, destino e porta conforme a ordem conhecida das ACLs.</p></div><form method="get" action="/agenda/simulador" class="card card-body mb-3"><div class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label">IP do dispositivo</label><input class="form-control" name="ip" required value="<?=h($ip)?>" placeholder="192.168.1.20"></div><div class="col-md-3"><label class="form-label">Destino (domínio ou IP)</label><input class="form-control" name="destino" value="<?=h($destino)?>" placeholder="exemplo.com.br"></div><div class="col-md-2"><label class="form-label">Protocolo</label><select class="form-select" name="protocolo"><option value="http" <?=$protocolo==='http'?'selected':''?>>HTTP</option><option value="https" <?=$protocolo==='https'?'selected':''?>>HTTPS</option></select></div><div class="col-md-2"><label class="form-label">Porta</label><input class="form-control" type="number" min="1" max="65535" name="porta" value="<?=h((string)$porta)?>"></div><div class="col-md-3"><label class="form-label">Data e hora</label><input class="form-control" type="datetime-local" name="quando" required value="<?=h($quando)?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Simular</button></div></div></form><?php if($resultado):?><div class="card"><div class="card-body"><div class="text-muted small">Resultado calculado · <?=h(strtoupper($resultado['protocolo']))?>:<?=h((string)$resultado['porta'])?> · <?=h($resultado['destino']?:'destino não informado')?></div><h4 class="mt-1"><span class="badge bg-<?=($resultado['decisao']==='permitir'?'success':($resultado['decisao']==='bloquear'?'danger':'secondary'))?>"><?=h($resultado['decisao'])?></span></h4><div>Grupo detectado: <strong><?=h($resultado['grupo']['nome']??'nenhum grupo associado')?></strong></div><?php if($resultado['dominio_regra']):?><div>Regra de domínio: <strong><?=h($resultado['dominio_regra']['tipo'])?></strong> (<?=h($resultado['dominio_regra']['dominio'])?>)</div><?php endif;?><div class="mt-2"><strong>Motivo:</strong> <?=h($resultado['motivo'])?></div><hr><strong>Regras de horário correspondentes</strong><?php if($resultado['regras']):?><ul class="mt-2"><?php foreach($resultado['regras'] as $r):?><li><?=!empty($resultado['vencedora']) && $r['id']===$resultado['vencedora']['id']?'<strong>Vencedora:</strong> ':''?><?=h($r['nome'])?> — <?=h($r['acao'])?> (<?=h($r['grupo_nome']??'todos os grupos')?>)</li><?php endforeach;?></ul><?php else:?><p class="text-muted mt-2">Nenhuma regra de horário corresponde ao período.</p><?php endif;?><div class="alert alert-info mb-0"><?=h($resultado['aviso'])?></div></div></div><?php endif;?>
